### `tool_executor.py` — Python Tool Functions

```python name=tool_use_agent/tool_executor.py
import math
import json
from datetime import datetime

# ─────────────────────────────────────────
# TOOL IMPLEMENTATIONS
# ─────────────────────────────────────────

def calculator(expression: str) -> str:
    """Safely evaluates a math expression."""
    try:
        allowed_funcs = {k: v for k, v in math.__dict__.items() if not k.startswith("_")}
        result = eval(expression, {"__builtins__": {}}, allowed_funcs)
        return f"Result: {result}"
    except Exception as e:
        return f"Error evaluating expression: {e}"

def get_weather(city: str) -> str:
    """Simulated weather lookup."""
    data = {
        "paris":     "18°C, Partly Cloudy",
        "london":    "12°C, Rainy",
        "new york":  "22°C, Sunny",
        "tokyo":     "25°C, Clear",
        "sydney":    "20°C, Windy",
        "hyderabad": "35°C, Hot and Humid",
        "mumbai":    "32°C, Humid",
        "berlin":    "10°C, Overcast",
    }
    return data.get(city.lower(), f"Weather data unavailable for '{city}'.")

def web_search(query: str) -> str:
    """Simulated web search."""
    kb = {
        "population of india":          "India's population is ~1.44 billion (2024).",
        "capital of france":            "The capital of France is Paris.",
        "ceo of openai":                "Sam Altman is the CEO of OpenAI.",
        "python latest version":        "Python 3.12 is the latest stable version (2024).",
        "azure openai models":          "Azure OpenAI supports GPT-4o, GPT-4, GPT-3.5-turbo.",
        "tallest building in the world":"The Burj Khalifa in Dubai is the tallest at 828 meters.",
    }
    for key, val in kb.items():
        if any(word in query.lower() for word in key.split()):
            return val
    return f"No results found for: '{query}'"

def get_current_datetime(timezone: str = "UTC") -> str:
    """Returns current UTC datetime."""
    now = datetime.utcnow()
    return f"Current UTC Date/Time: {now.strftime('%Y-%m-%d %H:%M:%S')}"

def unit_converter(value: float, from_unit: str, to_unit: str) -> str:
    """Converts between common units."""
    conversions = {
        ("km", "miles"):       lambda v: v * 0.621371,
        ("miles", "km"):       lambda v: v * 1.60934,
        ("kg", "pounds"):      lambda v: v * 2.20462,
        ("pounds", "kg"):      lambda v: v * 0.453592,
        ("celsius", "fahrenheit"): lambda v: (v * 9/5) + 32,
        ("fahrenheit", "celsius"): lambda v: (v - 32) * 5/9,
        ("meters", "feet"):    lambda v: v * 3.28084,
        ("feet", "meters"):    lambda v: v * 0.3048,
    }
    key = (from_unit.lower(), to_unit.lower())
    if key in conversions:
        result = conversions[key](value)
        return f"{value} {from_unit} = {round(result, 4)} {to_unit}"
    return f"Conversion from '{from_unit}' to '{to_unit}' is not supported."

# ─────────────────────────────────────────
# TOOL REGISTRY
# ─────────────────────────────────────────
TOOL_REGISTRY = {
    "calculator":           calculator,
    "get_weather":          get_weather,
    "web_search":           web_search,
    "get_current_datetime": get_current_datetime,
    "unit_converter":       unit_converter,
}

def execute_tool(tool_name: str, tool_args: dict) -> str:
    """Dispatches a tool call by name with args."""
    if tool_name not in TOOL_REGISTRY:
        return f"Error: Tool '{tool_name}' not found. Available: {list(TOOL_REGISTRY.keys())}"
    try:
        return TOOL_REGISTRY[tool_name](**tool_args)
    except Exception as e:
        return f"Tool execution error: {e}"
```

### `agent.py` — Tool Use Agent Core

```python name=tool_use_agent/agent.py
import os
import json
from openai import AzureOpenAI
from dotenv import load_dotenv
from tool_definitions import TOOL_DEFINITIONS
from tool_executor import execute_tool

load_dotenv()

# ─────────────────────────────────────────
# AZURE OPENAI CLIENT
# ─────────────────────────────────────────
client = AzureOpenAI(
    azure_endpoint=os.getenv("AZURE_OPENAI_ENDPOINT"),
    api_key=os.getenv("AZURE_OPENAI_API_KEY"),
    api_version=os.getenv("AZURE_OPENAI_API_VERSION"),
)
DEPLOYMENT = os.getenv("AZURE_OPENAI_DEPLOYMENT")

SYSTEM_PROMPT = """
You are a helpful AI assistant with access to tools.
Use the available tools whenever needed to answer accurately.
Always reason carefully before selecting a tool.
If you have enough information, respond directly without calling a tool.
"""

# ─────────────────────────────────────────
# TOOL USE AGENT LOOP
# ─────────────────────────────────────────
def tool_use_agent(user_message: str, max_steps: int = 5) -> str:
    print(f"\n{'='*60}")
    print(f"🚀 TOOL USE AGENT STARTED")
    print(f"❓ Question: {user_message}")
    print(f"{'='*60}\n")

    messages = [
        {"role": "system", "content": SYSTEM_PROMPT},
        {"role": "user",   "content": user_message},
    ]

    for step in range(1, max_steps + 1):
        print(f"🔄 Step {step}/{max_steps}")
        print("-" * 40)

        # ── CALL AZURE OPENAI WITH TOOLS ─────────
        response = client.chat.completions.create(
            model=DEPLOYMENT,
            messages=messages,
            tools=TOOL_DEFINITIONS,
            tool_choice="auto",   # LLM decides: call tool OR respond directly
            temperature=0.0,
            max_tokens=1000,
        )

        response_message = response.choices[0].message
        finish_reason    = response.choices[0].finish_reason

        print(f"📡 Finish Reason: {finish_reason}")

        # ── CASE 1: LLM wants to call tool(s) ────
        if finish_reason == "tool_calls":
            tool_calls = response_message.tool_calls

            # Append assistant's tool_call message
            messages.append({
                "role":       "assistant",
                "content":    response_message.content,
                "tool_calls": [
                    {
                        "id":       tc.id,
                        "type":     "function",
                        "function": {
                            "name":      tc.function.name,
                            "arguments": tc.function.arguments
                        }
                    }
                    for tc in tool_calls
                ]
            })

            # Execute each tool call
            for tc in tool_calls:
                tool_name = tc.function.name
                tool_args = json.loads(tc.function.arguments)

                print(f"🔧 Tool Called : {tool_name}")
                print(f"📥 Arguments   : {json.dumps(tool_args, indent=2)}")

                result = execute_tool(tool_name, tool_args)
                print(f"✅ Result      : {result}\n")

                # Append tool result back to messages
                messages.append({
                    "role":         "tool",
                    "tool_call_id": tc.id,
                    "content":      result,
                })

        # ── CASE 2: LLM gives final answer ───────
        elif finish_reason == "stop":
            final_answer = response_message.content
            print(f"\n{'='*60}")
            print(f"🏁 FINAL ANSWER:\n{final_answer}")
            print(f"{'='*60}")
            return final_answer

    return "Max steps reached without a final answer."
```

